VALUES ('yue-r3', '夫谭', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '越国早期君主，夫谭。在位时越国尚弱，处于吴国阴影之下，无力争霸，国势平平，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夫谭"}]'::jsonb, NULL, NULL, '夫谭')
