VALUES ('yue-r4', '允常', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '允常，勾践之父。在位时越国与吴国时有争战，国势渐起，为勾践霸业奠基，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/允常"}]'::jsonb, NULL, NULL, '允常')
