VALUES ('gou-jian', '勾践', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '先败于夫差，屈身臣吴后反击灭吴，称霸东南。「卧薪尝胆」典出其事，越国霸业巅峰，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/勾践"}]'::jsonb, NULL, NULL, '勾践')
