VALUES ('yue-r7', '不寿', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '勾践之子，不寿。在位时吴国已亡，越国内部渐有纷争，国势转衰，无力维持霸业，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/不寿"}]'::jsonb, NULL, NULL, '不寿')
