VALUES ('yue-r9', '翳', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '迁都琅邪，分封诸子于各地。越国由盛转衰，内乱加剧，诸侯离心，霸业渐失，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/翳"}]'::jsonb, NULL, NULL, '翳')
