VALUES ('yue-r10', '错枝', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位仅两年，为弟所弑。越国内乱频仍，国势继续衰落，无力维持霸主地位，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/错枝"}]'::jsonb, NULL, NULL, '错枝')
