VALUES ('yue-r11', '无余', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位十一年，越国继续衰落，无力维持霸主地位，诸侯纷纷自立，国势转弱，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无余"}]'::jsonb, NULL, NULL, '无余')
