VALUES ('yue-r12', '无颛', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位近二十年，越国内乱不止，诸侯纷纷自立，国势奄奄一息，濒临分裂，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无颛"}]'::jsonb, NULL, NULL, '无颛')
