VALUES ('yue-r13', '无彊', ARRAY[]::text[], '姒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '越国末代君主，无彊。扩张过度，遭楚、齐攻杀，越国分裂，霸业终结，国亡，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无彊"}]'::jsonb, NULL, NULL, '无彊')
