VALUES ('fan-li', '范蠡', ARRAY[]::text[], NULL, NULL, -536, 1, NULL, 'year', -448, 1, NULL, 'year', ARRAY['政治家','军事家'], '春秋末楚国人，字少伯，仕越为大夫，与文种辅佐越王勾践复国灭吴。越国称霸后辞官离去，辗转齐、陶经商致富，后世尊称陶朱公；晚年事迹多带传说色彩。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/范蠡"}]'::jsonb, NULL, NULL, NULL)
